function benefitMarkup(row){return `<div class="benefit-item level-benefit" data-required="${row.level||0}"><span class="benefit-glyph" aria-hidden="true">${row.icon}</span><div class="benefit-copy"><strong>${row.title}</strong><small>${row.description}</small><span class="locked-label">Terbuka mulai Level ${row.level||1}</span></div><button type="button" data-modal="${row.id}" aria-label="Lihat detail ${row.title}"><span class="lock-icon">${lockIcon}</span><span class="link-arrow">↗</span></button></div>`}
const namesForLevel=['Starter Seller','Emerging Seller','Growing Seller','Scaling Seller','Commercial Partner'];const requirementsForLevel=['Mulai Rp0','Branding Rp60 juta atau GMV Max Rp20 juta','Branding Rp150 juta atau GMV Max Rp50 juta','Branding Rp1,5 miliar atau GMV Max Rp500 juta','Branding Rp3 miliar atau GMV Max Rp1 miliar'];
const features=document.querySelector('#features');features.innerHTML=`<div class="levels-intro"><div><span class="level-kicker">BENEFIT EXPLORER</span><h3>Manfaat di setiap langkah</h3><p>Spending 30 hari terakhir · pilih salah satu kategori. Manfaat level sebelumnya tetap tersedia; frekuensi Konsultasi VIP mengikuti level tertinggi dan tidak dijumlahkan.</p></div><span class="levels-count">05 LEVEL</span></div>${namesForLevel.map((name,index)=>{const level=index+1,rows=benefitRows.filter(x=>(x.displayLevel||x.level)===level);return `<details class="level-section" data-level="${level}" ${level===1?'open':''}><summary><span class="level-number">${String(level).padStart(2,'0')}</span><span class="level-section-title"><strong>Level ${level} <span>· ${name}</span></strong><small>${requirementsForLevel[index]}</small></span><span class="level-state"></span><span class="level-chevron" aria-hidden="true">⌄</span></summary><div class="level-content">${rows.length?rows.map(benefitMarkup).join(''):'<p class="level-empty">Benefit Level 4 tetap berlaku untuk Level 5. Paket pada gambar mengelompokkan benefit Level 4 dan 5 bersama.</p>'}</div></details>`}).join('')}<details class="level-section extra-section"><summary><span class="level-number">✧</span><span class="level-section-title"><strong>Jelajahi juga</strong><small>Kelas, simulasi & informasi tambahan</small></span><span class="level-chevron" aria-hidden="true">⌄</span></summary><div class="level-content">${additionalRows.map(benefitMarkup).join('')}</div></details>`;
const subtitles={'Learning Center':'Belajar TikTok Ads dengan panduan praktis.','Kelas':'Belajar langsung bersama praktisi TikTok Ads.','Konsultasi VIP':'Review, evaluasi, dan optimasi TikTok Ads, TikTok Shop, serta TikTok One.','Rekomendasi':'Temukan peluang untuk mengoptimalkan iklan.','Asisten TikTok Ads via MCP':'Asisten TikTok Ads via MCP sedang dalam persiapan.','TikTok Kolaborasi Plus':'Dukungan affiliate untuk brand dan seller.','TikTok Market Scope':'Temukan insight pasar untuk bisnismu.','TikTok Symphony':'Buat konten sosial media dengan bantuan AI.','TikTok Content Suite':'Kelola dan temukan konten yang sesuai kebutuhan brand.','TikTok Creator Marketing':'Temukan kreator yang tepat untuk brand.','TikTok Commercial Partnership Solutions':'Dukungan kolaborasi untuk kebutuhan brand.','Bantu pilih yang cocok':'Temukan dukungan konten yang sesuai kebutuhanmu.'};
const learning={'TikTok Ads':['Panduan Lengkap GMV Max untuk Seller TikTok Ads','TTMS & Consideration Ads','TikTok Market Scope'],'TikTok Shop':['Collaboration Plus','Strategi Manajemen Toko TikTok Ads 2026'],'TikTok One':['TikTok One: Tips & Trik untuk Seller TikTok Ads','TikTok Symphony','TikTok One: Content Suite','TikTok One: Creator Marketing']};
function bodyFor(id){if(id==='Learning Center')return `<p>Materi dapat membantu brand memahami TikTok Ads, GMV Max, dan fitur TikTok lainnya.</p><div class="chips"><span>Pahami strategi</span><span>Pelajari contoh</span><span>Terapkan pada iklan</span></div>${Object.entries(learning).map(([k,v])=>`<div class="modal-card"><h3>${k}</h3>${v.map(x=>`<div class="material">${x}<button type="button" data-material="${x}">Buka materi ↗</button></div>`).join('')}</div>`).join('')}`;if(id==='Kelas')return `<h3>Jadwal kelas JJTA</h3><div class="modal-card"><small>ROADSHOW YOGYAKARTA</small><h3>Cuan di 11.11 & 12.12 pakai TikTok Consideration Ads & TikTok One</h3><p>Sabtu, 07 November 2026 · 10.00–selesai WIB</p><p>Waktu Luang De Loji</p><a href="https://www.google.com/maps/search/?api=1&query=Waktu+Luang+De+Loji+Jl.+Panembahan+Senopati+No.38+Yogyakarta" target="_blank">Buka Google Maps ↗</a> · <a href="https://brand.hanindo.co.id/jurus-jitu-tiktok-ads/kelas/kelas-offline-jjta-yogyakarta-november-2026" target="_blank">Lihat Detail Kelas ↗</a></div><h3>Jadwal roadshow berikutnya</h3><div class="modal-card"><strong>Bandung</strong><p>23 November 2026 · Segera hadir</p></div><div class="modal-card"><strong>Surabaya</strong><p>18 Desember 2026 · Segera hadir</p></div><label>Filter jadwal <select><option>Semua</option><option>Akan datang</option><option>Sudah lewat</option></select></label>`;if(id==='Konsultasi VIP')return `<p>Setiap sesi berfokus pada satu tema utama dan dilengkapi tindak lanjut yang terarah.</p><div class="chips"><span>Bahas kendala</span><span>Tentukan prioritas</span><span>Dapat arahan optimasi</span></div><div class="modal-card"><label>Consultation date · WIB<input type="date"></label><label>Consultation time · WIB<select><option>10:00</option><option>11:00</option><option>13:00</option><option>14:00</option><option>15:00</option></select></label><label>Goal and main challenges<textarea></textarea></label><p>Select your preferred time. The team will confirm the schedule after reviewing your request.</p></div>`;if(id==='TikTok Symphony')return `<p>Perangkat kreatif AI dari TikTok membantu brand memproduksi konten dalam skala besar.</p><div class="chips"><span>Foto dan brief</span><span>Review video</span><span>Posting dan iklankan</span></div><div class="modal-card"><h3>Symphony Agent</h3><p>Demo lokal · data dan proses contoh</p><p>Assistant: Pilih foto produk contoh dan kirim arahan videomu. Gambar kopi dapat ditambahkan sebagai referensi gaya.</p><label><input type="checkbox" checked style="width:auto"> Foto produk Veraldo</label><br><label><input type="checkbox" style="width:auto"> Referensi gaya (opsional)</label><br><label>Brief video<textarea id="brief">Buat video review produk Veraldo dengan suasana santai di mall, perlihatkan detail produk dan tutup dengan ajakan mencoba.</textarea></label><button class="action" id="send-demo">Kirim brief demo</button><p id="demo-result"></p></div>`;if(id==='Bantu pilih yang cocok')return `<p>Pilih kebutuhan kontenmu:</p><div class="chips"><button class="action" data-modal="TikTok Symphony">Buat konten dengan AI</button><button class="action" data-modal="TikTok Content Suite">Cari konten</button><button class="action" data-modal="TikTok Creator Marketing">Kolaborasi kreator</button></div>`;return `<p>${subtitles[id]}</p><div class="modal-card"><h3>${id}</h3><p>${id==='Asisten TikTok Ads via MCP'?'Dalam persiapan': 'Pelajari manfaat dan dukungan yang tersedia untuk brand Anda.'}</p></div>`}
const overlay=document.querySelector('#overlay');function benefitAccess(id){const row=benefitRows.find(item=>item.id===id),level=getQualifiedLevel(),locked=row&&level<row.level;const access=row?`<div class="modal-card benefit-access"><strong>${locked?'Pratinjau · belum terbuka':'Tersedia mulai Level '+row.level}</strong><p>${row.level===1?'Mulai Rp0':requirementsForLevel[row.level-1]} · spending 30 hari terakhir. ${row.level===1?'':'Cukup salah satu kategori mencapai batas; spending tidak dijumlahkan.'}</p><p>Level simulasi saat ini: ${level}. ${locked?'Penuhi syarat level ini untuk membuka benefit.':'Benefit ini tersedia dalam simulasi.'}</p></div>`:'';return access}function openModal(id){document.querySelector('#modal-title').textContent=id;document.querySelector('#modal-sub').textContent=subtitles[id]||'';document.querySelector('#modal-body').innerHTML=benefitAccess(id)+bodyFor(id);overlay.classList.add('open');document.body.style.overflow='hidden';overlay.querySelector('.close').focus()}function closeModal(){overlay.classList.remove('open');document.body.style.overflow=''}document.addEventListener('click',e=>{const b=e.target.closest('[data-modal]');if(b)openModal(b.dataset.modal);if(e.target.closest('.close')||e.target===overlay)closeModal();if(e.target.id==='send-demo')document.querySelector('#demo-result').textContent='Brief diterima dalam simulasi. Symphony akan menyiapkan konsep video berdasarkan arahanmu.';if(e.target.dataset.material)window.open('https://brand.hanindo.co.id/jurus-jitu-tiktok-ads','_blank')});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
const spendThresholds={branding:[0,60000000,150000000,1500000000,3000000000],gmv:[0,20000000,50000000,500000000,1000000000]};
const spendFields={branding:document.querySelector('#spend-branding'),gmv:document.querySelector('#spend-gmv')};let activeRoute='branding';let budget=spendFields.branding;const gauge=document.querySelector('#gauge');const stops=[...spendThresholds.branding],names=['Starter Seller','Emerging Seller','Growing Seller','Scaling Seller','Commercial Partner'];
function getSpends(){return {branding:Number(spendFields.branding.value.replace(/\D/g,''))||0,gmv:Number(spendFields.gmv.value.replace(/\D/g,''))||0}}
function getQualifiedLevel(values=getSpends()){for(let i=4;i>=1;i--)if(values.branding>=spendThresholds.branding[i]||values.gmv>=spendThresholds.gmv[i])return i+1;return 1}
function setActiveRoute(route){activeRoute=route;budget=spendFields[route];stops.splice(0,stops.length,...spendThresholds[route]);document.querySelectorAll('[data-spend-route]').forEach(btn=>{const selected=btn.dataset.spendRoute===route;btn.classList.toggle('is-active',selected);btn.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('.spend-field').forEach(el=>el.classList.toggle('is-active',el.dataset.route===route))}
function update(n,format=true){n=Math.max(0,Math.min(Number.MAX_SAFE_INTEGER,Number(n)||0));if(format)budget.value=n.toLocaleString('id-ID');const values=getSpends(),level=getQualifiedLevel(values);document.querySelector('#level').textContent='Level '+level;document.querySelector('#seller').textContent=names[level-1];document.querySelectorAll('.benefit-item').forEach(el=>{const required=+el.dataset.required,locked=required>0&&level<required;el.classList.toggle('is-locked',locked);const button=el.querySelector('button');button.setAttribute('aria-label',button.getAttribute('aria-label').split(' — ')[0]+(locked?' — pratinjau, terbuka mulai Level '+required:''))});document.querySelectorAll('.level-section[data-level]').forEach(el=>{const requirement=+el.dataset.level,attained=level>=requirement,current=level===requirement;el.classList.toggle('is-current',current);el.classList.toggle('is-unlocked',attained);el.classList.toggle('is-future',!attained);el.querySelector('.level-state').textContent=current?'LEVEL KAMU':attained?'TERBUKA':'TERKUNCI'});document.documentElement.style.setProperty('--tier-progress',`${level*20}%`);document.documentElement.style.setProperty('--tier-turn',`${level*72}deg`);const next=document.querySelector('#next-milestone');if(next)next.textContent=level===5?'Level tertinggi tercapai':`Level ${level+1} · Branding atau GMV Max`}
for(const [route,input] of Object.entries(spendFields)){input.addEventListener('focus',()=>{setActiveRoute(route);if(typeof refreshPresetLabels==='function')refreshPresetLabels()});input.addEventListener('input',()=>{setActiveRoute(route);update(input.value.replace(/\D/g,''));if(typeof refreshPresetLabels==='function')refreshPresetLabels()})}setActiveRoute('branding');update(0);
